-- Marketing Hub publish script for the TiDB SQL console. Run after 0249.
-- Paste one line at a time. Every statement is exactly one line, every table is
-- cabinet_dealz.<table>, and nothing here drops, updates, or deletes a row.
--
-- What this does: publishes the real Marketing Hub content that lived in the frontend
-- before PR #20 (ff372a1) moved it into the database: sales scripts, training guides,
-- recommended video channels, training PDFs, and social captions. The 0218
-- 'EXAMPLE DRAFT:' rows stay exactly as they are: unpublished, not deleted.
-- 56 inserts: guide 4, link 10, pdf 16, script 14, social 8, video 4.
--
-- Safe to re-run: every INSERT is INSERT ... SELECT ... WHERE NOT EXISTS on type +
-- title, so a row that already exists by that pair is skipped.
--
-- Newlines inside the body text are written as \n escapes, so run this with the
-- session's normal sql_mode (backslash escapes on, which is the TiDB default).
-- The text contains non-ASCII characters and emoji, so keep the connection utf8mb4.
--
-- Third-party YouTube channels are recommended, not affiliated. @KitchenBathDesignTV,
-- @salesinsightslab, and @Houzz are intentionally absent: those handles 404.
--
-- Run the read-only checks first, then the inserts, then the last two checks.

-- check 0 (read-only): confirm this session honours backslash escapes. sql_mode must not
-- include NO_BACKSLASH_ESCAPES, or every newline escape below lands as a literal backslash-n.
SELECT @@sql_mode AS sqlMode;

-- check 1 (read-only): published rows by type, before
SELECT type, COUNT(*) AS rowCount FROM cabinet_dealz.affiliate_resources WHERE isPublished = 1 GROUP BY type ORDER BY type;

-- check 2 (read-only): total rows, and how many are still unpublished drafts
SELECT COUNT(*) AS totalRows, SUM(CASE WHEN isPublished = 0 THEN 1 ELSE 0 END) AS draftRows FROM cabinet_dealz.affiliate_resources;

-- check 3 (read-only): confirm the 0218 example drafts are still unpublished and present
SELECT COUNT(*) AS exampleDraftRows FROM cabinet_dealz.affiliate_resources WHERE title LIKE 'EXAMPLE DRAFT:%' AND isPublished = 0;

-- inserts: 56 statements, one per line
