-- script · Phone Introduction
INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'script', 'Phone Introduction', 'Hi [Name], I''m [Your Name] — I run a cabinet store called [Your Store Name]. I work with homeowners who are remodeling their kitchens and want quality cabinets at a fair price. Are you or anyone you know thinking about updating their kitchen?\n\nKey rule: always end with a question. Questions keep the conversation going.', NULL, 'phone', NULL, 102, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'script' AND title = 'Phone Introduction');
-- script · Present the Quote — Walk Through Pricing
INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'script', 'Present the Quote — Walk Through Pricing', 'Once the design is done, the quote is built from it. Walk the customer through it line by line.\n\nHow to present:\n- Start with the total: "Your complete kitchen in [door style] comes to $X."\n- Break it down by section: uppers, lowers, tall cabinets, specialty pieces\n- Remind them what''s included: all boxes, doors, hardware, soft-close hinges\n- Address shipping: "Shipping is calculated based on your ZIP code and will be added at checkout."\n\nNever apologize for the price. Your pricing is competitive with big box stores but the quality is significantly better. If they push back, use the objection responses.', NULL, 'in-store', NULL, 103, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'script' AND title = 'Present the Quote — Walk Through Pricing');
-- script · Follow-Up Text (Day 3)
INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'script', 'Follow-Up Text (Day 3)', 'Hey [Name], just wanted to make sure you got my message! Here''s my store link again: [your storefront URL]. We have a 3D Designer so you can plan your whole kitchen before you order. No pressure — just wanted you to have it.', NULL, 'follow-up', NULL, 104, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'script' AND title = 'Follow-Up Text (Day 3)');
-- script · Design Tool Invitation
INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'script', 'Design Tool Invitation', 'I wanted to share something cool — there''s a free kitchen design tool on my site where you can lay out your whole kitchen and see different door styles. Takes about 10 minutes and gives you a real price. Want to try it? [your storefront URL]', NULL, 'follow-up', NULL, 105, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'script' AND title = 'Design Tool Invitation');
