INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'script', 'After Sending a Quote', 'Hey [Name], I sent over the quote for your kitchen. Let me know if you have any questions or want to tweak anything. I''m happy to jump on a call and walk through it with you.', NULL, 'follow-up', NULL, 106, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'script' AND title = 'After Sending a Quote');
-- script · Objection Handling Responses
INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'script', 'Objection Handling Responses', 'Every sale has objections. The customer who objects is still engaged — they just need more information or reassurance.\n\n- "It''s too expensive." → "Compared to what? Let me show you what the same kitchen costs at [big box store]. Our price is usually 20–40% less for better quality."\n- "I need to think about it." → "Of course — what''s the main thing you want to think through? I want to make sure you have everything you need to decide."\n- "I''m not sure about the quality." → "That''s a fair question. Our cabinets are [all-plywood construction / dovetail joints / soft-close standard]. Would it help to see some photos of installed kitchens?"\n- "I want to get other quotes." → "Absolutely — you should. When you get them, compare the box construction (plywood vs. particleboard) and what''s included. I''m confident we''ll be competitive."\n- "I need to talk to my spouse." → "Of course. Would it help if I sent you a summary you could share with them? Or we could do a quick call together."', NULL, 'objection', NULL, 107, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'script' AND title = 'Objection Handling Responses');
-- script · Closing — Ask for the Order
INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'script', 'Closing — Ask for the Order', 'Most salespeople lose the sale because they never ask for it. Closing is simply asking the customer to make a decision.\n\nSimple closes:\n- "Are you ready to move forward? I can get your order placed today."\n- "If the pricing works for you, the next step is just a deposit to lock in your order. Want to do that now?"\n- "What would it take for you to feel comfortable moving forward today?"\n\nThe deposit close: "We require a 50% deposit to begin processing your order. The balance is due before shipping. Want me to send you the payment link?"\n\nIf they say yes — stop talking and process the order. If they say no — ask what''s stopping them and handle the objection.', NULL, 'closing', NULL, 108, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'script' AND title = 'Closing — Ask for the Order');
-- script · Referral Request (After Delivery)
INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'script', 'Referral Request (After Delivery)', 'Hey [Name]! Hope the kitchen is looking amazing! If you know anyone else thinking about updating their kitchen, I''d love an introduction. Just forward them my store link: [your storefront URL] — I''ll take great care of them!', NULL, 'closing', NULL, 109, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'script' AND title = 'Referral Request (After Delivery)');
-- script · Introduction Email
INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'script', 'Introduction Email', 'Subject: Beautiful Kitchen Cabinets — Contractor Pricing, No Contractor Required\n\nHi [Name],\n\nMy name is [Your Name] and I run [Your Store Name], a cabinet store specializing in quality kitchen cabinets at pricing most homeowners never get access to.\n\nI work directly with a national cabinet network to offer contractor-grade cabinets — the same quality you''d see in a high-end remodel — at prices that are typically 20–40% less than big box stores.\n\nYou can browse our full selection and use our free kitchen design tool here: [your storefront URL]\n\nIf you''re thinking about updating your kitchen — or know someone who is — I''d love to help. Reply to this email or call/text me at [your phone number].\n\n[Your Name]\n[Your Store Name]\n[your storefront URL]', NULL, 'email', NULL, 110, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'script' AND title = 'Introduction Email');
-- script · Follow-Up Email (After No Response)
INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'script', 'Follow-Up Email (After No Response)', 'Subject: Quick follow-up — [Your Store Name]\n\nHi [Name],\n\nI wanted to follow up on my last message. I know life gets busy!\n\nIf you''re still thinking about your kitchen, I''d love to put together a free quote for you. All I need is your kitchen dimensions and your preferred door style — and I can have a price to you within 24 hours.\n\nHere''s my store if you want to browse styles first: [your storefront URL]\n\nNo pressure at all — just here when you''re ready.\n\n[Your Name]', NULL, 'email', NULL, 111, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'script' AND title = 'Follow-Up Email (After No Response)');
