INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'script', 'Facebook Post', '🏠 Thinking about updating your kitchen? I can help!\n\nI run [Your Store Name] — a cabinet store offering beautiful, quality kitchen cabinets at prices most homeowners never see. We carry dozens of door styles and our free online design tool lets you plan your whole kitchen before you spend a dollar.\n\n👉 Browse styles and get a free quote: [your storefront URL]', NULL, 'social', NULL, 112, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'script' AND title = 'Facebook Post');
