INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'social', 'Facebook — General Awareness', '🏠 Thinking about updating your kitchen? I can help!\n\nI run [Your Store Name] — a cabinet store offering beautiful, quality kitchen cabinets at prices most homeowners never see. We carry dozens of door styles from classic white shaker to modern slab, and our free online design tool lets you plan your whole kitchen before you spend a dollar.\n\n👉 Browse styles and get a free quote: [your storefront URL]\n\nQuestions? Drop them in the comments or send me a message!', NULL, 'caption', NULL, 500, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'social' AND title = 'Facebook — General Awareness');
