INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'social', 'Facebook — Before/After (When You Have a Photo)', '🔥 Kitchen transformation alert!\n\nThis customer came to me with a dated kitchen and a budget. We designed their new layout together using our online tool, ordered the cabinets, and look at the result!\n\nIf your kitchen needs a refresh, let''s talk. I''ll help you design it, price it, and make it happen.\n\n👉 [your storefront URL]', NULL, 'caption', NULL, 501, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'social' AND title = 'Facebook — Before/After (When You Have a Photo)');
-- social · Facebook — Design Tool Feature
INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'social', 'Facebook — Design Tool Feature', 'Did you know you can design your entire kitchen online — for free — before buying a single cabinet?\n\nOur design tool lets you:\n✅ Enter your kitchen dimensions\n✅ Place cabinets exactly where you want them\n✅ See different door styles and colors\n✅ Get a real price instantly\n\nNo salesperson pressure. No showroom appointment. Just you, your kitchen, and a plan.\n\nTry it here: [your storefront URL]', NULL, 'caption', NULL, 502, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'social' AND title = 'Facebook — Design Tool Feature');
-- social · Instagram — Door Styles and Finishes
INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'social', 'Instagram — Door Styles and Finishes', 'Kitchen goals 🤍 Swipe to see the door styles we carry — from classic shaker to sleek modern slab. Every style is available in multiple colors and finishes.\n\n📐 Free design tool on our site — plan your whole kitchen in 10 minutes.\n💰 Contractor pricing. No contractor required.\n\nLink in bio → [your storefront URL]', NULL, 'caption', '{"hashtags":["#kitchenremodel","#kitchencabinets","#kitchendesign","#homeimprovement","#kitchenrenovation","#cabinetry","#dreamkitchen"]}', 503, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'social' AND title = 'Instagram — Door Styles and Finishes');
-- social · Instagram — Contractor/Trade
INSERT INTO cabinet_dealz.affiliate_resources (type, title, body, url, category, metaJson, sortOrder, isPublished, featured) SELECT 'social', 'Instagram — Contractor/Trade', 'Contractors and builders — let''s talk. 🔨\n\nI supply quality kitchen cabinets to trade professionals at pricing that protects your margin. Fast quotes, reliable delivery, and a design tool your clients can use to visualize the finished kitchen.\n\nDM me or visit: [your storefront URL]', NULL, 'caption', '{"hashtags":["#contractor","#builder","#kitchenremodel","#cabinetry","#tradeprofessional","#homebuilder"]}', 504, TRUE, FALSE FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cabinet_dealz.affiliate_resources WHERE type = 'social' AND title = 'Instagram — Contractor/Trade');
