-- check 4 (read-only): the newline escapes were honoured. Expect 0.
-- A non-zero count means the session had NO_BACKSLASH_ESCAPES set.
SELECT COUNT(*) AS rowsWithoutRealNewline FROM cabinet_dealz.affiliate_resources WHERE isPublished = 1 AND type IN ('guide', 'script') AND body IS NOT NULL AND body NOT LIKE CONCAT('%', CHAR(10), '%');

-- check 5 (read-only): published rows by type, after. Expect guide 4, link 10, pdf 16, script 14, social 8, video 4.
SELECT type, COUNT(*) AS rowCount FROM cabinet_dealz.affiliate_resources WHERE isPublished = 1 GROUP BY type ORDER BY type;
